// PARCHXA calculator runtime — renders one catalog calculator into `[data-calc-slug]`.
//
// The page shell is generated by tools/calc-pages.mjs and carries the SEO content; this module
// only adds the interactive form and live results (progressive enhancement). It reads the pure
// definition from the shared catalog, so the maths is identical to the tests and the generator.

import "../app.js";
import { getCalculator, getCategory, CALCULATORS } from "./catalog.js";
import { CURRENCIES, DEFAULT_CURRENCY, formatValue } from "./format.js";

const KEY_CURRENCY = "parchxa.calc.currency.v1";
const KEY_RECENT = "parchxa.calc.recent.v1";

const el = (tag, attrs = {}, ...kids) => {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v == null || v === false) continue;
    if (k === "class") node.className = v;
    else if (k === "text") node.textContent = v;
    else if (k === "html") node.innerHTML = v;
    else if (k.startsWith("on") && typeof v === "function") node.addEventListener(k.slice(2), v);
    else if (v === true) node.setAttribute(k, "");
    else node.setAttribute(k, v);
  }
  node.append(...kids.filter((k) => k != null));
  return node;
};

const storage = {
  get(key, fallback) { try { const v = localStorage.getItem(key); return v == null ? fallback : v; } catch { return fallback; } },
  set(key, value) { try { localStorage.setItem(key, value); } catch {} },
  getJSON(key, fallback) { try { const v = JSON.parse(localStorage.getItem(key) || "null"); return v == null ? fallback : v; } catch { return fallback; } },
};

function pushRecent(slug) {
  const list = storage.getJSON(KEY_RECENT, []);
  const next = [slug, ...list.filter((s) => s !== slug)].slice(0, 12);
  storage.set(KEY_RECENT, JSON.stringify(next));
}

// ---------------------------------------------------------------- chart
function lineChart(points, ctx, format = "currency") {
  const valid = (points || []).filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y));
  if (valid.length < 2) return null;
  const W = 600, H = 220, pad = 34;
  const xs = valid.map((p) => p.x), ys = valid.map((p) => p.y);
  const xMin = Math.min(...xs), xMax = Math.max(...xs);
  const yMin = Math.min(...ys, 0), yMax = Math.max(...ys);
  const sx = (x) => pad + ((x - xMin) / (xMax - xMin || 1)) * (W - pad * 2);
  const sy = (y) => H - pad - ((y - yMin) / (yMax - yMin || 1)) * (H - pad * 2);
  const path = valid.map((p, i) => `${i ? "L" : "M"}${sx(p.x).toFixed(1)},${sy(p.y).toFixed(1)}`).join(" ");
  const last = valid[valid.length - 1];
  const accent = getComputedStyle(document.documentElement).getPropertyValue("--accent").trim() || "#6c7cff";
  const svg = `
    <svg class="calc-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Projection chart" preserveAspectRatio="none">
      <line x1="${pad}" y1="${sy(0)}" x2="${W - pad}" y2="${sy(0)}" stroke="#26334a" stroke-width="1"/>
      <path d="${path}" fill="none" stroke="${accent}" stroke-width="2.5"/>
      <circle cx="${sx(last.x).toFixed(1)}" cy="${sy(last.y).toFixed(1)}" r="4" fill="${accent}"/>
      <text x="${pad}" y="16" fill="#9ba9bd" font-size="12">${escapeText(formatValue(yMax, format, ctx))}</text>
      <text x="${pad}" y="${H - 8}" fill="#9ba9bd" font-size="12">${escapeText(String(valid[0].x))}</text>
      <text x="${W - pad}" y="${H - 8}" text-anchor="end" fill="#9ba9bd" font-size="12">${escapeText(String(last.x))}</text>
    </svg>`;
  const wrap = el("div");
  wrap.innerHTML = svg;
  return wrap;
}
function escapeText(s) { return String(s).replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }

// ---------------------------------------------------------------- render
function render(root, calc) {
  const category = getCategory(calc.category);
  // remember for the "recently used" list on the directory / home page
  pushRecent(calc.slug);
  if (category) root.dataset.category = calc.category;

  const inputsWrap = el("div", { class: "calc-inputs" });
  const fields = new Map();
  const errorNodes = new Map();

  if (calc.currency) {
    const select = el("select", { id: `cur-${calc.slug}` });
    for (const c of CURRENCIES) select.append(el("option", { value: c.code, text: `${c.code} — ${c.name}`, selected: c.code === storage.get(KEY_CURRENCY, DEFAULT_CURRENCY) }));
    const field = el("div", { class: "calc-field calc-currency" }, el("label", { for: select.id, text: "Currency" }), select);
    inputsWrap.append(field);
    fields.set("__currency", select);
  }

  for (const inp of calc.inputs) {
    const id = `f-${calc.slug}-${inp.key}`;
    let control;
    if (inp.type === "select") {
      control = el("select", { id, name: inp.key });
      for (const opt of inp.options || []) control.append(el("option", { value: opt.value, text: opt.label, selected: String(opt.value) === String(inp.default) }));
    } else if (inp.type === "date") {
      control = el("input", { id, name: inp.key, type: "date", value: inp.default });
    } else if (inp.type === "text") {
      control = el("input", { id, name: inp.key, type: "text", value: inp.default ?? "", autocomplete: "off" });
    } else {
      control = el("input", { id, name: inp.key, type: "number", value: inp.default ?? "", min: inp.min, max: inp.max, step: inp.step ?? "any", inputmode: "decimal" });
    }
    const err = el("span", { class: "calc-error", role: "alert", hidden: true });
    const field = el("div", { class: "calc-field" }, el("label", { for: id, text: inp.label }), control, inp.help ? el("span", { class: "calc-help", text: inp.help }) : null, err);
    inputsWrap.append(field);
    fields.set(inp.key, control);
    errorNodes.set(inp.key, { field, err });
  }

  const resultBox = el("div", { class: "calc-result", "aria-live": "polite" });
  const actions = el("div", { class: "calc-actions" },
    el("button", { type: "button", class: "button button-secondary button-small", text: "Reset", onclick: () => { for (const i of calc.inputs) { const f = fields.get(i.key); if (i.type === "select") f.value = i.default; else f.value = i.default ?? ""; } compute(); } }),
    el("button", { type: "button", class: "button button-secondary button-small", text: "Copy result", onclick: copyResult }),
    el("button", { type: "button", class: "button button-secondary button-small", text: "Print", onclick: () => window.print() }),
  );

  let lastText = "";
  function copyResult() {
    try { navigator.clipboard.writeText(`${calc.h1}\n${lastText}\n${location.href}`); } catch {}
  }

  function collect() {
    const values = {};
    let ok = true;
    for (const inp of calc.inputs) {
      const control = fields.get(inp.key);
      const { field, err } = errorNodes.get(inp.key);
      field.classList.remove("is-invalid"); err.hidden = true;
      if (inp.type === "number") {
        const raw = String(control.value).trim();
        if (raw === "") {
          if (inp.optional) { values[inp.key] = 0; continue; }
          ok = false; field.classList.add("is-invalid"); err.hidden = false; err.textContent = "Enter a value"; continue;
        }
        const n = Number(raw);
        if (!Number.isFinite(n)) { ok = false; field.classList.add("is-invalid"); err.hidden = false; err.textContent = "Enter a number"; continue; }
        if (inp.min != null && n < inp.min) { ok = false; field.classList.add("is-invalid"); err.hidden = false; err.textContent = `Minimum is ${inp.min}`; continue; }
        if (inp.max != null && n > inp.max) { ok = false; field.classList.add("is-invalid"); err.hidden = false; err.textContent = `Maximum is ${inp.max}`; continue; }
        values[inp.key] = n;
      } else {
        values[inp.key] = control.value;
      }
    }
    return { values, ok };
  }

  function compute() {
    const { values, ok } = collect();
    const currency = calc.currency ? fields.get("__currency").value : DEFAULT_CURRENCY;
    if (calc.currency) storage.set(KEY_CURRENCY, currency);
    const ctx = { currency };
    resultBox.replaceChildren();
    if (!ok) {
      resultBox.append(el("p", { class: "calc-verdict", text: "Fix the highlighted fields to see a result." }));
      lastText = "";
      return;
    }
    let result;
    try { result = calc.run(values, ctx); }
    catch (error) {
      resultBox.append(el("p", { class: "calc-verdict", text: error && error.message ? error.message : "These values do not produce a result." }));
      lastText = "";
      return;
    }
    if (!result || !result.primary) { resultBox.append(el("p", { class: "calc-verdict", text: "No result." })); return; }

    resultBox.append(el("div", { class: "calc-primary" }, el("span", { text: result.primary.label }), el("strong", { text: formatValue(result.primary.value, result.primary.format, ctx) })));
    if (result.stats && result.stats.length) {
      const stats = el("div", { class: "calc-stats" });
      for (const s of result.stats) stats.append(el("div", { class: "calc-stat" }, el("span", { text: s.label }), el("strong", { text: formatValue(s.value, s.format, ctx) }), s.hint ? el("small", { text: s.hint }) : null));
      resultBox.append(stats);
    }
    if (result.verdict) resultBox.append(el("p", { class: "calc-verdict", text: result.verdict }));
    if (result.chart) { const chart = lineChart(result.chart.points, ctx, result.chart.format || "currency"); if (chart) resultBox.append(chart); }
    if (result.steps && result.steps.length) {
      const list = el("ol", { class: "calc-steps" });
      for (const s of result.steps) list.append(el("li", { text: s }));
      resultBox.append(list);
    }
    if (result.table && result.table.rows && result.table.rows.length) {
      const table = el("table", { class: "data-table" });
      const thead = el("thead");
      const hr = el("tr");
      for (const col of result.table.columns || []) hr.append(el("th", { text: col.label, style: col.align ? `text-align:${col.align}` : null }));
      thead.append(hr); table.append(thead);
      const tbody = el("tbody");
      for (const row of result.table.rows) {
        const tr = el("tr");
        for (const cell of row) {
          const isObj = cell && typeof cell === "object" && "v" in cell;
          tr.append(el("td", { text: isObj ? formatValue(cell.v, cell.format || "number", ctx) : String(cell) }));
        }
        tbody.append(tr);
      }
      table.append(tbody);
      const wrap = el("div", { class: "table-wrap" }, table);
      if (result.table.caption) resultBox.prepend(el("p", { class: "calc-help", text: result.table.caption }));
      resultBox.append(wrap);
    }
    lastText = `${result.primary.label}: ${formatValue(result.primary.value, result.primary.format, ctx)}`;
  }

  let raf = 0;
  const schedule = () => { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; compute(); }); };
  for (const control of fields.values()) { control.addEventListener("input", schedule); control.addEventListener("change", schedule); }

  const app = el("div", { class: "calc-app" }, inputsWrap, resultBox, actions);
  root.replaceChildren(app);
  compute();
}

const root = document.querySelector("[data-calc-slug]");
if (root) {
  const calc = getCalculator(root.dataset.calcSlug);
  if (calc) render(root, calc);
  else root.append(el("p", { class: "notice", text: "This calculator could not be loaded." }));
}

// Keep the reference to the full catalog for tests/tools that import this module in Node.
export const _catalog = CALCULATORS;
